#!/bin/sh
set -eu
cd "$(dirname "$0")"
if [ ! -f .env ]; then
    printf '%s\n' '먼저 test/oracle/에서 make up으로 테스트 DB를 준비하세요.' >&2
    exit 1
fi
# .env is a local shell-compatible file generated by env.sh.
set -a
. ./.env
set +a
export LAZYORA_INTEGRATION=1
cd ../..
go test ./test/oracle -run '^TestOracle(Free|Program|Workflow|Plan|Export|FullExport|Reconnect|Output|Routine|Completion|Format|Definition|Relations|Pages|LOBs|GridEdit)Integration$' -v -count=1
